LatinWords, strippedLatinWords, EnglishWords = set(), [], []
for wordMapEntry in LATIN_WORD_MAP:
    assert len(wordMapEntry) == 2, f"{wordMapEntry}"
    LatinWord,EnglishWord = wordMapEntry
    assert isinstance( LatinWord, str ) and len(LatinWord)>=2, f"{LatinWord=}"
    assert LatinWord != EnglishWord, f"Attempting to replace identical Latin word: {LatinWord=}"
    assert LatinWord not in LatinWords, f"duplicate LatinWord: {LatinWord=} ({EnglishWord=})"
    if LatinWord.startswith(' ') or EnglishWord.startswith(' '): assert LatinWord.startswith(' '), f"Mismatched leading space: {LatinWord=} {EnglishWord=}"
    if LatinWord.endswith(' ') or EnglishWord.endswith(' '): assert LatinWord.endswith(' '), f"Mismatched trailing space: {LatinWord=} {EnglishWord=}"
    # assert LatinWord not in EnglishWord, f"Recursive substitution of '{LatinWord}' into '{EnglishWord}'"
    assert '  ' not in LatinWord, f"{LatinWord=}"
    assert 'W' not in LatinWord, f"{LatinWord=}" f""
    if LatinWord not in ('immowashis',' revewash'): assert 'w' not in LatinWord, f"{LatinWord=}"
    assert 'Ä' not in LatinWord, f"{LatinWord=}" f""; assert 'ä' not in LatinWord, f"{LatinWord=}"
    assert 'ö' not in LatinWord, f"{LatinWord=}"
    assert 'ß' not in LatinWord, f"{LatinWord=}"
    assert 'Ü' not in LatinWord; assert 'ü' not in LatinWord, f"{LatinWord=}"
    LatinWords.add( LatinWord ); strippedLatinWords.append( LatinWord.strip() )
    if LatinWord.startswith(' '): assert EnglishWord.startswith(' '), f"Mismatched leading space:  {LatinWord=} {EnglishWord=}"
    if LatinWord.endswith(' '): assert EnglishWord.endswith(' '), f"Mismatched trailing space: {LatinWord=} {EnglishWord=}"
    if EnglishWord[-1] in ' ,.:;':
        assert LatinWord[-1] == EnglishWord[-1], f"Mismatched trailing character: {LatinWord=} {EnglishWord=}"
    if LatinWord[-1] in ' ,.:;' and LatinWord not in ('Joan.',' litt.'):
        assert EnglishWord[-1] == LatinWord[-1], f"Mismatched trailing character: {LatinWord=} {EnglishWord=}"
    assert '  ' not in EnglishWord, f"{EnglishWord=}"
    if ' ' not in LatinWord.strip():
        assert ' ' not in EnglishWord.strip(), f"Space in middle of {EnglishWord=}" # No space in middle
    EnglishWords.append( EnglishWord )
print( f"Have {len(strippedLatinWords):,} Latin words.")
del LatinWords, strippedLatinWords, EnglishWords

# English words introduced by the translation table keep their normal j spelling.
# Bible names still follow the existing j/J -> y/Y pronunciation convention.
_ENGLISH_WORDS_WITH_J = frozenset((
    'adjacent','adjoining','adjoins','adjusted','conjecture','conjunction','dejection','eject','ejected','ejecting',
    'ejects','enjoin','enjoined','enjoins','enjoy','enjoyable','enjoyed','enjoying','enjoys','injured','injuries',
    'injury','injustice','january','jar','jars','jasper','jaundice','javelin','javelins','jaw','jaws','jealous',
    'jealousy','jew','jewel','jeweller','jewels','jewish','join','joined','joining','joins','joint','jointly','joints',
    'joked','joking','jot','journey','journeys','joy','joyful','joys','jubilation','jubilee','jubilees','judaism',
    'judge','judged','judgement','judgements','judges','judging','judicial','jugs','jump','jumped','jumping','jumps',
    'junction','junctions','june','juniper','junipers','just','justices','justification','justified','justify',
    'justifying','jut','juts','jutting','majesty','majority','objection','perjured','perjuries','prejudge','prejudged',
    'prejudges','projecting','projection','projections','reject','rejected','rejecting','rejection','rejoice',
    'rejoiced','rejoices','rejoicing','subject','subjected','subjecting','subjection','subjects','subjugate',
    'subjugated','subjugates','uninjured','unjust','unjustly',
    ))

def translateLatin( htmlStr:str ) -> str:
    """
    Do basic word-for-word translation from Latin Vulgate Bible to English.

    Text in htmlStr parameter can be inside a span,
        e.g., '<span class="Wycl_verseTextChunk">ech man in his seruice, and in the offring,</span>'
    """
    if (DEBUGGING_THIS_MODULE) or BibleOrgSysGlobals.debugFlag:
        fnPrint( DEBUGGING_THIS_MODULE, f"translateLatin( ({len(htmlStr)}) )" )

    # NOTE: Didn't work because it's already html, so added back to table above with '>'
    # if html.startswith( 'et '): # Handle common exception that can't be expressed in the word table
    #     html = f'and {html[3:]}'
    # elif html.startswith( 'qui '):
    #     html = f'who {html[4:]}'
    # Adjacent footnote keyword/text spans sometimes omit their separating space.
    # Repair those field boundaries before matching words; keep the markup intact.
    htmlStr = re.sub( r'(?<=[\w.;:])(</span><span class="f[kt]">)(?=\w)', r' \1', htmlStr )
    # Missing spaces within the source commentary, before word matching.
    for sourceTypo,correctedText in (
            ('AUG.Mystice.', 'AUG. Mystice.'),
            ('CAS.Mystice.', 'CAS. Mystice.'),
            ('ID.Latrones', 'ID. Latrones'),
            ('esca.Mystice', 'esca. Mystice'),
            ('Psal.III.', 'Psal. III.'),
            ):
        htmlStr = htmlStr.replace(sourceTypo, correctedText)
    for LatinWord,EnglishWord in LATIN_WORD_MAP:
        htmlStr = htmlStr.replace( LatinWord, EnglishWord )
        if LatinWord[0] == ' ':
            htmlStr = htmlStr.replace( f'>{LatinWord[1:]}', f'>{EnglishWord[1:]}' )


    # Protect whole English words before respelling names, including words next to underscores.
    htmlStr = re.sub( r'[A-Za-z]+',
        lambda match: match[0] if match[0].lower() in _ENGLISH_WORDS_WITH_J
            else match[0].replace('j','y').replace('J','Y'), htmlStr )

    return ( htmlStr # Try to write names like they might have sounded
                # But then need to fix up some regular English words
                .replace('(ay)','(aj)')
                .replace('conyunction','conjunction')
                .replace(' eyect',' eject')
                .replace('inyect','inject')
                .replace('inyur','injur') # injure, injury
                .replace('yanitor','janitor')
                .replace('yealous','jealous').replace('Yew','Jew').replace('yewel','jewel')
                .replace('yoin','join').replace(' yot ',' jot ').replace('yourney','journey').replace('yoy','joy')
                .replace('yubil','jubil') # jubilee(s), jubilation
                .replace('Yudge','Judge').replace('yudg','judg') # judge, judging
                .replace('yump','jump')
                .replace('Yust ','Just ').replace('yust','just').replace('Yusti','Justi')
                .replace('Yhes','Jhes') # Change these ones back again -- 'Jhesus' -- was maybe more like French J ???
                .replace('mayest','majest').replace('mayor','major')
                .replace('obyect','object')
                .replace('proyect','project')
                .replace('peryur','perjur')
                .replace('reyect','reject').replace('reyoic','rejoic')
                .replace('subyect','subject')
                .replace('adyacent','adjacent')
                .replace('deyect','deject')
                .replace('eyect','eject')
                .replace('Eyect','Eject')
                .replace('Reyoic','Rejoic')
                .replace('Yoy','Joy')
                .replace('Inyur','Injur')
                .replace('Yubil','Jubil')
                .replace('Yudaism','Judaism')
                .replace('Yudg','Judg')
                .replace('yudici','judici')
                .replace('Yudici','Judici')
                .replace('Yust','Just')
                .replace('Mayest','Majest')
                .replace('Subyect','Subject')
                .replace('Yump','Jump')
                .replace('yostl','jostl')
                .replace('soyourn','sojourn')
                .replace('yavelin','javelin')
                .replace('subyug','subjug')
                .replace('yuice','juice')
            )
# end of VulgateLatinToEnglish.translateLatin



